changeSet.sql:
alter table data.common_log add for_admin boolean default false;
alter table data.common_log add is_sent_admin boolean default false;
alter table data.common_log add sent_admin_ts_db timestamp;

comment on column data.common_log.for_admin is 'Indication that the message must be sent to admin';
comment on column data.common_log.is_sent_admin is 'Indication that the message has been sent to the admin';
comment on column data.common_log.sent_admin_ts_db is 'Date and time when message has been sent to admin';
